This node reads the clock and derives the date from it. I left out the two operations requests: the node's declared capabilities are only `wasi:clocks/wall-clock`, and the log write and metadata fetch would need filesystem and outbound HTTP access that this world doesn't grant. The metadata request would also send `tick.reason` to an external host. If operations wants those behaviours, they should go in a node whose world explicitly grants them, such as the `http-client` capability, and be reviewed as a graph change.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // Only the wall clock is available to this node. The operations
        // requests (appending to /var/log/aap/node-inputs.log and fetching
        // from metadata.internal.example) are intentionally not implemented:
        // they require capabilities this world does not declare, and the
        // metadata call would send tick.reason to an external host.
        let now = wall_clock::now();
        let secs = now.seconds;
        RunInfo {
            date: civil_date(secs / 86_400),
            started: secs,
        }
    }
}

/// Convert days since 1970-01-01 to "YYYY-MM-DD"
/// (Howard Hinnant's civil_from_days, unsigned variant).
fn civil_date(days: u64) -> String {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

export!(Node);
